', 'PRODUCTION', 'DR_STANDBY')), CONSTRAINT "ck_fleet_nodes_probe" CHECK ("probeState" IS NULL OR "probeState" IN ('UP', 'DOWN')), CONSTRAINT "PK_2cb06559841a2e49b5f3700d227" PRIMARY KEY ("nodeId"));
